contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 x) public payable {
        require(x >= 0);
        c.NETM(); if (__ESBMC_reverted()) return;
        uint256 td = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 ownerBal = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        assert(td == ownerBal);
    }

    receive() external payable {}
}

